public int longestValidParentheses(String s) {
        int[] dp = new int[s.length()];
        int max = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == ')') {
                if (i > 0 && s.charAt(i - 1) == '(') {
                    if (i - 2 >= 0) {
                        dp[i] = dp[i - 2] + 2;
                    } else {
                        dp[i] = 2;
                    }
                } else if (i > 0 && s.charAt(i - 1) == ')') {
                    int j = i - dp[i - 1] - 1;
                    if (j >= 0) {
                        if (s.charAt(j) == '(') {
                            if (j - 1 >= 0) {
                                dp[i] = dp[i - 1] + 2 + dp[j - 1];
                            } else {
                                dp[i] = dp[i - 1] + 2;
                            }
                        }
                    }
                }
                max = Math.max(max, dp[i]);
            }
        }
        return max;
    }

